mapper.select:
select *
from student_award as sa join student_information si on sa.student_number = si.student_number


        AND sa.student_name LIKE CONCAT('%',#{studentName},'%')


        AND sa.student_number LIKE CONCAT('%',#{studentNumber},'%')


        AND si.classes = #{classes}


        AND si.grade = #{grade}


        AND si.major = #{major}


        AND si.college = #{college}
